@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32)):
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(1):
            r = c * 4 + t * 4
            v = kt.unpack(kt.load(x[r : r + 4, :]))
            a = kt.absolute(kt.math("sub", v, 1.0))
            b = kt.xrot(a, 1)
            lt = kt.math("cmplt", b, 0.0)
            gt = kt.math("cmpgt", b, 0.0)
            kt.store(y[r : r + 4, :], lt + gt)
